insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TOTAL_BUCKET_B","title":"¿Cuántas carreras suma el partido?","description":"Elige el rango. Se corrige con el marcador final.","category":"total","difficulty":"hard","points":6,"answerType":"multiple","options":[{"id":"0a4","label":"0 a 4"},{"id":"5a7","label":"5 a 7"},{"id":"8a10","label":"8 a 10"},{"id":"11p","label":"11 o más"}],"rule":{"op":"buckets","fact":"total","buckets":[{"id":"0a4","label":"0 a 4","min":0,"max":4},{"id":"5a7","label":"5 a 7","min":5,"max":7},{"id":"8a10","label":"8 a 10","min":8,"max":10},{"id":"11p","label":"11 o más","min":11,"max":null}]},"priority":1,"cooldown":2,"tags":["total","rango"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;